INSERT INTO temp_import_pages VALUES ('{"pageId": "e0470000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 47, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "47", "printedPageNumber": 47, "pdfPageNumber": 430, "sequenceIndex": 37, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0470100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith VIII", "sourceIdentifier": "VIII", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0470000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 47"}, {"id": "f0470100-0000-4000-8000-000000000001", "structuralNodeId": "b0470100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith VIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 47"}, {"id": "f0470200-0000-4000-8000-000000000001", "structuralNodeId": "b0470100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "روي أنه عليه الصلاة والسلام قال من ترك الصلاة حتى مضى وقتها ثم قضى عذب في النار حقبا والحقب ثمانون سنة والسنة ثلاثمائة وستون يوما كل يوم كان مقداره ألف سنة هكذا في مجالس الأبرار", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 47"}, {"id": "f0470300-0000-4000-8000-000000000001", "structuralNodeId": "b0470100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) is reported to have said, \"A person neglecting his salaat (even though he makes it up later) shall remain in Hell for a period of one Haqb. A Haqb is equal to eighty years of three hundred and sixty days each, and a day in the Hereafter shall equal one thousand years of this world.\"\n\nAbul Laith Samarqandi (Rahmatullah alaih) is responsible for the hadith in which the Prophet (Sallallaho alaihe wasallam) is reported to have said, \"The name of a person who neglects even a single fardh salaat intentionally is written on the gate of the Hell, which he must enter.\" Hadhrat Ibn Abbas (Radhiyallaho anho) narrates that once the Prophet (Sallallaho alaihe wasallam) said, \"Pray, O Allah! cause not any one of us to be a wretched destitute.\" He then said: \"Do you know who is a wretched destitute?\" At the request of the companions, he explained to them saying, \"A wretched destitute is he who neglects his salaat. In Islaam there is nothing for him.\" In another hadith it is said, \"Allah will not care a bit for the person who has been neglecting salaat intentionally, and for him shall be an awful doom.\"\n\nIt is reported in a hadith that ten persons will be specially tormented, and one of them will be the person who neglects his salaat. It is said that his hands will be tied while the angels shall smite him on his face and back. Paradise will tell him, ''In me there is no room for you,'' and Hell will say to him, ''Come to me. You are for me and I am for you.'' It is also reported that there is a valley in Hell named Lamlam. This valley is infested with serpents as fat as the neck of a camel and as long as one month''s journey. A person neglecting salaat shall be tormented in this valley. In another hadith, it is reported that there is a vale in the Hell, which is known as the Pit of Grief; it is infested with scorpions of the size of a mule. This place is also meant for tormenting the people who neglect salaat. Of course, there is nothing to worry if the most merciful Allah", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 47"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0480000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 48, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "48", "printedPageNumber": 48, "pdfPageNumber": 431, "sequenceIndex": 38, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0480100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith IX", "sourceIdentifier": "IX", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0480000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}, {"id": "f0480100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "pardons the sins. But are we really prepared to ask for His pardon?\n\nIbn Hajar writes, \"A woman died. Her brother was present at her burial. By chance his purse fell into the grave and was buried with the dead body. The brother realized this after he had returned home and was very sorry for the loss. He decided to dig up the grave secretly and take out the purse. When he dug it up, he saw that the pit was in flames. He returned home, stricken with grief, and related the story to his mother, and inquired if she knew why it was so. The mother informed him that his sister used to delay in salaat and offered it after its fixed hours. May Allah save us from these habits!", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}, {"id": "f0480200-0000-4000-8000-000000000001", "structuralNodeId": "b0480100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith IX", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}, {"id": "f0480300-0000-4000-8000-000000000001", "structuralNodeId": "b0480100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ لا سهم في الإسلام لمن لا صلاة له ولا صلاة لمن لا وضوء له أخرجه البزار وأخرج الحاكم عن عائشة مرفوعا وصححه قلت أظن لا سهم لمن لا صلاة له سهم في الإسلام كمن لا سهم له وسهام الإسلام الصوم والصلاة والصدقة الحديث وأخرج الطبراني في الأوسط عن ابن عمر مرفوعا لا دين لمن لا صلاة له إنما موضع الصلاة من الدين كموضع الرأس من الجسد كذا في الدر المنثور", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}, {"id": "f0480400-0000-4000-8000-000000000001", "structuralNodeId": "b0480100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"There is no place in Islaam for a person who does not say his salaat, and there is no salaat without wudhu.\" Hadhrat Abdullah bin Umar (Radhiyallaho anho) also heard the Prophet (Sallallaho alaihe wasallam) saying, \"There is no Islaam in a person when there is no salaat by him. The position of salaat in Islaam is as the position of the head in a body.\"\n\nLet those who do not offer salaat, and not only call themselves Muslims, but also boast of their being champions of the Muslim cause, ponder over these words of the Holy Prophet (Sallallaho alaihe wasallam). They dream of reviving the past glory of Islaam, but would not care to know how rigidly the people responsible for that glory stuck to the practices of Islaam.\n\nHadhrat Abdullah bin Abbas (Radhiyallaho anho) suffered from cataract of the eye. People told him that the disease could be treated, but he would have to miss his salaat for a few days. He said: \"This is not possible; I have heard", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0490000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 49, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "49", "printedPageNumber": 49, "pdfPageNumber": 432, "sequenceIndex": 39, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0490000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 49"}, {"id": "f0490100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "the Prophet (Sallallaho alaihe wasallam) saying, \"A person who does not say his salaat shall stand before Allah while Allah shall be angry with him.\" The companions of the Prophet would rather like to go blind than to forego salaat (though permissible under such circumstances) even for a few days. When on his last day Hadhrat Umar (Radhiyallaho anho) was stabbed by a Majoos, he often remained unconscious and eventually died due to excessive bleeding. While on his death-bed, he was made conscious of the approaching salaat hours and he performed salaat in that very condition, and would remark: \"There is no lot in Islaam for a person who does not say his salaat.\" These days it is considered unkind and improper to induce the patient or even allow him to say his salaat. What a world of difference is there between the view-points and approach of the Muslims of these two ages!\n\nHadhrat Ali (Radhiyallaho anho) once requested the Prophet (Sallallaho alaihe wasallam) to give him a servant. The Prophet (Sallallaho alaihe wasallam) said \"Here are three slaves; take anyone you like.\" Hadhrat Ali (Radhiyallaho anho) said, \"You may kindly choose one for me.\" The Prophet (Sallallaho alaihe wasallam) pointed towards a certain man and said, \"Take this one; he is particular about his salaat. But you are not to beat him. We are forbidden to beat one who says salaat.\" We, on the other hand, mock at our servant and consider him a liability if he goes for salaat.\n\nSufyaan Thauri (Rahmatullah alaih), the famous Soofi once fell into a state of ecstasy. He remained in his house for seven days without sleep, food and drink. When his Shaikh was informed of his condition, he inquired if Sufyaan was observing the hours of his salaat. He was told that his salaat was quite regular and safe. At this, the Shaikh remarked, \"Glory be to Allah, Who has not allowed the Devil to have an upper hand on him!\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 49"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
